/*
 * image.h - embedded brick images (generated by tools/png2c.py)
 */
#ifndef SGIL2_IMAGE_H
#define SGIL2_IMAGE_H

typedef struct {
    unsigned short       width;
    unsigned short       height;
    const unsigned char *palette;   /* 256 * RGB */
    unsigned long        datalen;
    const unsigned char *data;      /* PackBits RLE of width*height indices */
} EmbImage;

/* malloc'd width*height*3 RGB buffer, NULL on corrupt data */
unsigned char *img_decode_rgb(const EmbImage *img);

#endif
